data = {
    "n": 18,
    "date": "September 3, 2025",
    "turns": turns
}

path = "benchmark/longchat/sessions/session_18.json"
with open(path, "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

with open(path, "r", encoding="utf-8") as f:
    loaded = json.load(f)

full_text = json.dumps(loaded)
required = [
    "Jennifer Calloway",
    "praised the prose",
    "pacing slow until chapter 6",
    "cutting chapters 2 and 3 down by half",
    "Quentin Marsh",
    "Elizabeth Strout meets Andre Dubus III",
    "Annie Bloom's Books",
    "launch event",
    "The Hollow Years",
    "too generic",
]

print("n={}, date={}, turns={}".format(loaded["n"], loaded["date"], len(loaded["turns"])))
all_found = True
for phrase in required:
    found = phrase in full_text
    if not found:
        all_found = False
    print("{}: {}".format("FOUND" if found else "MISSING", phrase))

words = sum(len(t["content"].split()) for t in loaded["turns"])
print("\nTotal word count: {}".format(words))
print("All required facts found: {}".format(all_found))
